import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.CmvPqeTF.js";const S=JSON.parse('{"title":"设置与主题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1791351888000}'),r={name:"guide/settings.md"};function i(l,t,c,n,h,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="设置与主题" tabindex="-1">设置与主题 <a class="header-anchor" href="#设置与主题" aria-label="Permalink to &quot;设置与主题&quot;">​</a></h1><p>设置入口：左条底部齿轮图标，或原生菜单 <strong>vShell → Settings...（<code>⌘,</code>）</strong>。520px 模态，分「界面 / 终端 / 快捷键」三个标签页，全部改动即时保存到 <code>localStorage</code>。</p><p>应用主题（浅色 / 深色）与语言（中 / 英）在<strong>顶部工具栏岛右侧</strong>切换，<code>⌘⇧T</code> 也可切换主题。主色为固定品牌色（IDEA 蓝：亮 <code>#3871E1</code> / 暗 <code>#3574F0</code>），不再提供主题色选项——岛式 accent 是一组联动色（选中、悬停、标签底等六个伴生值），单色块无法派生整组。</p><hr><h2 id="_1-界面" tabindex="-1">1. 界面 <a class="header-anchor" href="#_1-界面" aria-label="Permalink to &quot;1. 界面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>取值</th></tr></thead><tbody><tr><td>字体</td><td>System / PingFang SC / Microsoft YaHei / Noto Sans SC / Source Han Sans / Helvetica / Arial</td></tr><tr><td>字号</td><td>11–18（滑块，刻度 11 / 13 / 16 / 18）</td></tr></tbody></table><h2 id="_2-终端" tabindex="-1">2. 终端 <a class="header-anchor" href="#_2-终端" aria-label="Permalink to &quot;2. 终端&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>取值</th></tr></thead><tbody><tr><td>字体</td><td>Menlo / Monaco / Courier New / Source Code Pro / JetBrains Mono / Fira Code / Cascadia Code / Noto Sans Mono</td></tr><tr><td>字号</td><td>10–24（滑块）</td></tr><tr><td>配色方案</td><td>默认 / Solarized 暗色 / Solarized 浅色 / Dracula / Monokai / One Dark</td></tr></tbody></table><p>字体、字号、配色修改对已打开的终端<strong>实时生效</strong>（无需重连）。终端行列数由窗口尺寸自动 fit，无需手工设置。</p><h2 id="_3-快捷键" tabindex="-1">3. 快捷键 <a class="header-anchor" href="#_3-快捷键" aria-label="Permalink to &quot;3. 快捷键&quot;">​</a></h2><p>7 项可自定义，点击条目进入「按键捕获」状态后按下新组合即可；「重置」恢复默认。</p><table tabindex="0"><thead><tr><th>动作</th><th>默认</th><th>状态</th></tr></thead><tbody><tr><td>新建连接</td><td><code>⌘/Ctrl+Shift+N</code></td><td>设置项存在，<strong>暂未接线</strong></td></tr><tr><td>关闭标签</td><td><code>⌘/Ctrl+W</code></td><td>由原生菜单实现</td></tr><tr><td>切换主题</td><td><code>⌘/Ctrl+Shift+T</code></td><td>✅</td></tr><tr><td>切换侧栏</td><td><code>⌘/Ctrl+B</code></td><td>✅</td></tr><tr><td>聚焦终端</td><td><code>⌘/Ctrl+`</code></td><td>设置项存在，<strong>暂未接线</strong></td></tr><tr><td>复制（终端）</td><td>macOS <code>⌘C</code>；Win/Linux <code>Ctrl+Shift+C</code></td><td>✅ 终端内拦截</td></tr><tr><td>粘贴（终端）</td><td>macOS <code>⌘V</code>；Win/Linux <code>Ctrl+Shift+V</code></td><td>✅ 终端内拦截</td></tr></tbody></table><p>全局快捷键在焦点位于输入框 / 文本域 / 下拉时自动跳过；终端内的键由终端单独处理（<code>Ctrl+C</code> / <code>Ctrl+V</code> 始终透传远端）。</p><h2 id="_4-原生菜单-macos" tabindex="-1">4. 原生菜单（macOS） <a class="header-anchor" href="#_4-原生菜单-macos" aria-label="Permalink to &quot;4. 原生菜单（macOS）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>快捷键</th><th>效果</th></tr></thead><tbody><tr><td>vShell → Settings...</td><td><code>⌘,</code></td><td>打开设置</td></tr><tr><td>File → Save</td><td><code>⌘S</code></td><td>保存当前激活的编辑器标签</td></tr><tr><td>File → Close</td><td><code>⌘W</code></td><td>断开当前标签所属连接并关闭标签</td></tr><tr><td>Edit</td><td><code>⌘Z</code> 等</td><td>系统标准编辑角色</td></tr></tbody></table><h2 id="_5-窗口" tabindex="-1">5. 窗口 <a class="header-anchor" href="#_5-窗口" aria-label="Permalink to &quot;5. 窗口&quot;">​</a></h2><ul><li>默认 1280×800，最小 960×600</li><li>macOS 隐藏原生标题栏；窗口为岛式画布（<code>#2B2D30</code> 暗色底），所有面板为独立圆角岛，岛间留白 6px</li><li>顶部主工具栏岛（40px）为唯一拖拽区，左侧预留 76px 红绿灯位；双击最大化</li><li>底部状态栏岛：左侧显示活动连接状态（连接中 / 已连接 / 已断开 / 无连接）与会话数，中间为传输摘要（点击直达 SFTP），右侧为侧栏 / 监控 / SFTP 的快速开关</li><li>连接建立过程中工具栏岛底缘有细进度条动画</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./terminal.html">终端使用</a></li></ul>',20)])])}const u=d(r,[["render",i]]);export{S as __pageData,u as default};
